#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Endpoint { pub node: String, pub port: u16 }
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Transport { Plain, Shielded }
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Envelope {
    pub transport: Transport,
    pub payload: Vec<u8>,
    pub client_tag: Option<String>,
    pub protocol: Option<u8>,
    pub peer: Endpoint,
    pub local: Endpoint,
}
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum DecodeError { Truncated, InvalidHeader, InvalidUtf8 }
#[derive(Clone, Debug, Default)]
pub struct EnvelopeDecoder;

pub fn is_shielded_prefix(bytes: &[u8]) -> bool { bytes.first() == Some(&0x5A) }

impl EnvelopeDecoder {
    pub fn decode(&self, bytes: &[u8], peer: Endpoint, local: Endpoint) -> Result<Envelope, DecodeError> {
        if !is_shielded_prefix(bytes) {
            return Ok(Envelope { transport: Transport::Plain, payload: bytes.to_vec(), client_tag: None, protocol: None, peer, local });
        }
        if bytes.len() < 5 { return Err(DecodeError::Truncated); }
        let tag_len = bytes[1] as usize;
        let payload_len = u16::from_be_bytes([bytes[3], bytes[4]]) as usize;
        let expected = 5usize.checked_add(tag_len).and_then(|n| n.checked_add(payload_len)).ok_or(DecodeError::InvalidHeader)?;
        if bytes.len() != expected { return Err(DecodeError::InvalidHeader); }
        let tag_bytes = &bytes[5..5 + tag_len];
        let client_tag = if tag_bytes.is_empty() { None } else {
            Some(std::str::from_utf8(tag_bytes).map_err(|_| DecodeError::InvalidUtf8)?.to_owned())
        };
        Ok(Envelope {
            transport: Transport::Shielded,
            payload: bytes[5 + tag_len..].to_vec(),
            client_tag,
            protocol: if bytes[2] == 0 { None } else { Some(bytes[2]) },
            peer,
            local,
        })
    }
}

