#[path = "solution.rs"]
mod solution;

use solution::{is_shielded_prefix, DecodeError, Endpoint, EnvelopeDecoder, Transport};

fn peer() -> Endpoint { Endpoint { node: "peer".into(), port: 10 } }
fn local() -> Endpoint { Endpoint { node: "local".into(), port: 20 } }

#[test]
fn prefix_detection_is_exact() {
    assert!(!is_shielded_prefix(&[]));
    assert!(!is_shielded_prefix(&[0x00, 0xa5]));
    assert!(is_shielded_prefix(&[0xa5]));
    assert!(is_shielded_prefix(&[0xa5, 0x00]));
}

#[test]
fn plain_inputs_include_empty_and_preserve_every_byte() {
    let decoder = EnvelopeDecoder;
    for bytes in [Vec::new(), vec![0], vec![1, 2, 3, 255]] {
        let before = bytes.clone();
        let envelope = decoder.decode(&bytes, peer(), local()).unwrap();
        assert_eq!(envelope.transport, Transport::Plain);
        assert_eq!(envelope.payload, bytes);
        assert_eq!(envelope.client_tag, None);
        assert_eq!(envelope.protocol, None);
        assert_eq!(envelope.peer, peer());
        assert_eq!(envelope.local, local());
        assert_eq!(bytes, before);
    }
}

#[test]
fn decodes_shielded_fields_and_zero_optionals() {
    let decoder = EnvelopeDecoder;
    let bytes = vec![0xa5, 3, 7, 0, 4, b'a', b'b', b'c', 0, 1, 2, 255];
    let envelope = decoder.decode(&bytes, peer(), local()).unwrap();
    assert_eq!(envelope.transport, Transport::Shielded);
    assert_eq!(envelope.client_tag, Some("abc".into()));
    assert_eq!(envelope.protocol, Some(7));
    assert_eq!(envelope.payload, vec![0, 1, 2, 255]);

    let empty = decoder.decode(&[0xa5, 0, 0, 0, 0], peer(), local()).unwrap();
    assert_eq!(empty.transport, Transport::Shielded);
    assert_eq!(empty.client_tag, None);
    assert_eq!(empty.protocol, None);
    assert!(empty.payload.is_empty());
}

#[test]
fn distinguishes_truncation_from_declared_length_errors() {
    let decoder = EnvelopeDecoder;
    for bytes in [&[0xa5][..], &[0xa5, 0][..], &[0xa5, 0, 0, 0][..]] {
        assert_eq!(decoder.decode(bytes, peer(), local()), Err(DecodeError::Truncated));
    }
    assert_eq!(decoder.decode(&[0xa5, 1, 1, 0, 1], peer(), local()), Err(DecodeError::InvalidHeader));
    assert_eq!(decoder.decode(&[0xa5, 0, 1, 0, 0, 9], peer(), local()), Err(DecodeError::InvalidHeader));
    assert_eq!(decoder.decode(&[0xa5, 0, 1, 0, 2, 9], peer(), local()), Err(DecodeError::InvalidHeader));
}

#[test]
fn invalid_tag_utf8_is_reported_without_mutating_input() {
    let decoder = EnvelopeDecoder;
    let bytes = vec![0xa5, 1, 1, 0, 0, 0xff];
    let before = bytes.clone();
    assert_eq!(decoder.decode(&bytes, peer(), local()), Err(DecodeError::InvalidUtf8));
    assert_eq!(bytes, before);
}

